const statusBadge=s=>badge(statusName(s),s?.startsWith('pending')?'pending':['error','denied'].includes(s)?'failed':'');
const views=[['overview','Overview','overview'],['portfolio','Portfolio & assets','wallets'],['activity','Transactions & activity','transactions'],['reports','Reports & analytics','history'],['manage','Manage & discover','apps'],['contacts','Contacts & labels','contacts'],['security','Security & account','settings']];
let data=demoData(),view='overview',live=false,loading=false,points=[],theme=localStorage.getItem('lens-theme')??'dark',palette=localStorage.getItem('lens-palette')??'purple';
let assetsQuery='',assetChain='all',hideDust=true,hideSpam=true,assetTab='tokens',selectedWallet='all';
let filters={query:'',kind:'all',status:'all',wallet:'all',from:'',to:''},activityPage=1,reportGrouping='daily',pluginQuery='',pluginResults=null,tokenResults=null,clientLog=[],lowBalance=Number(localStorage.getItem('lens-low-balance')??25),chartRange='30';
let pendingLive=null,sessionEpoch=0,privateMode=localStorage.getItem('lens-private-mode')==='1',bookScope=null,book={version:1,contacts:[],labels:{}},shownData=data,contactQuery='';
function preparePresentation(){const key=bookKey(data);if(key!==bookScope){if(bookScope!==null){$('dialog').close();$('dialogContent').innerHTML='';}bookScope=key;book=readBook(localStorage,key);contactQuery='';}const next={...data,transactions:data.transactions.map((r,i)=>({...decorateRecord(r,book),uiKey:String(i)}))};shownData=privateMode?redactWorkspace(next):next;}
function matchesLabel(r){return !filters.label||filters.label==='all'||[...(r.labels??[]),...(r.contactTags??[])].includes(filters.label);}
const uiAudit=(action,status,detail='')=>{clientLog.unshift({date:new Date().toISOString(),action,status,detail});clientLog=clientLog.slice(0,250);};
const holdings=()=>normalizeHoldings(shownData.portfolio??[]);
