const filteredRows=()=>recordFilter(shownData.transactions,{...filters,days:$('period').value}).filter(matchesLabel);
function toast(message){$('toast').textContent=privateMode?'Private mode is on. Turn it off to copy, export or view sensitive details.':message;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',7000);}
function dialog(html){$('dialogContent').innerHTML=html;$('dialog').showModal();}
$('close').onclick=()=>$('dialog').close();$('dialog').addEventListener('click',e=>{if(e.target===$('dialog'))$('dialog').close();});
function download(name,content,type){if(privateMode)return toast('Turn off private mode before exporting.');const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function applyTheme(){document.documentElement.dataset.private=String(privateMode);$('privacy').setAttribute('aria-pressed',String(privateMode));$('privacy').innerHTML=icon(privateMode?'eye-off':'eye')+(privateMode?'Private: on':'Private mode');document.documentElement.dataset.theme=theme;document.documentElement.dataset.palette=palette;$('theme').innerHTML=icon(theme==='dark'?'sun':'moon');$('palette').textContent=palette==='purple'?'B/W':'Purple';}
$('theme').onclick=()=>{theme=theme==='dark'?'light':'dark';localStorage.setItem('lens-theme',theme);applyTheme();};
$('palette').onclick=()=>{palette=palette==='purple'?'mono':'purple';localStorage.setItem('lens-palette',palette);applyTheme();};
$('privacy').onclick=()=>{privateMode=!privateMode;try{localStorage.setItem('lens-private-mode',privateMode?'1':'0');}catch{}$('dialog').close();$('dialogContent').innerHTML='';$('toast').textContent='';$('toast').style.display='none';filters={query:'',kind:'all',status:'all',wallet:'all',from:'',to:'',label:'all'};assetsQuery='';contactQuery='';pluginQuery='';selectedWallet='all';activityPage=1;render();};
$('period').onchange=()=>{activityPage=1;render();};
function navigate(next){view=next;render();window.scrollTo?.({top:0,behavior:'smooth'});}
function panel(title,sub,body,cls='',right=''){return `<section class="panel ${cls}"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${right}</div>${body}</section>`;}
function stat(label,value,note,iconName='wallets',cls=''){return `<article class="stat ${cls}"><div class="stat-label">${label}${icon(iconName,true)}</div><div class="stat-value">${value}</div><small>${note}</small></article>`;}
function empty(title,sub,action=''){return `<div class="empty"><span class="empty-icon">${icon('brand',true)}</span><h3>${title}</h3><p>${sub}</p>${action}</div>`;}
function walletCards(){return (shownData.wallets??[]).length?`<div class="wallet-grid">${shownData.wallets.map((w,i)=>{const p=(shownData.portfolio??[]).find(p=>p.address===w.address);return `<button class="wallet-tile" data-wallet="${esc(w.address??'')}"><div class="wallet-tile-top"><span class="coin wallet-symbol">${(w.family??detectAddress(w.address)?.family)==='solana'?'S':'E'}</span>${badge((w.chains??[]).join(' / ')||'Wallet')}</div><h3>${esc(w.name)}</h3><b class="wallet-value">${money(p?.total_usd)}</b><code>${esc(short(w.address))}</code><small>${esc(w.approvalMode==='autonomous'?'Autonomous access':w.approvalMode==='always_approve'?'Passkey approval required':w.approvalMode==='iframe'?'Confirm in signing window':'Access mode unavailable')} ${icon('arrow')}</small></button>`;}).join('')}</div>`:empty('Your wallets belong here','Connect PayBox to discover the wallets granted to this dashboard.',btn('Connect PayBox','connect','primary'));}
function demoPoints(){const start=Date.now()-29*86400000;return Array.from({length:30},(_,i)=>({time:start+i*86400000,value:i===29?1186.25:940+i*8+Math.sin(i*.8)*28}));}
function setPoints(){if(data.source==='demo'){points=demoPoints();return;}points=readSnapshots(localStorage,snapshotKey(data.wallets??[]));}
function captureSnapshot(){if(data.source!=='live')return;try{points=saveSnapshot(localStorage,snapshotKey(data.wallets??[]),data.balanceUsd);}catch{toast('Browser storage is unavailable. Snapshots stay in memory.');if(data.balanceUsd!=null)points.push({time:Date.now(),value:data.balanceUsd});}}
function lineChart(){if(privateMode)return `<div class="private-chart"><span>${icon('eye-off')}</span><h3>Value chart hidden</h3><p>Your balance and chart shape are hidden in private mode.</p></div>`;const shown=points.filter(p=>chartRange==='all'||p.time>=Date.now()-Number(chartRange)*86400000);if(!shown.length)return empty('Your value history starts here','Snapshots are saved every 15 minutes while the live dashboard is open. Historical values are not backfilled.',shownData.source==='live'?btn('Save a snapshot now','snapshot'):btn('Connect PayBox','connect','primary'));
 const minT=shown[0].time,maxT=shown.at(-1).time,min=Math.min(...shown.map(p=>p.value)),max=Math.max(...shown.map(p=>p.value)),pad=Math.max((max-min)*.2,max*.01,1),lo=Math.max(0,min-pad),hi=max+pad;const x=t=>shown.length===1?420:60+(t-minT)/(maxT-minT||1)*730,y=v=>215-(v-lo)/(hi-lo)*180;const path=shown.map((p,i)=>(i?'L':'M')+x(p.time).toFixed(1)+' '+y(p.value).toFixed(1)).join(' ');const change=shown.at(-1).value-shown[0].value;
 return `<div class="chart-summary"><span>${money(shown.at(-1).value)}</span><small class="${change>=0?'positive':'negative'}">${shown.length===1?'1 saved snapshot · next refresh in up to 15 minutes':(change>=0?'+':'')+money(change)+' <em>observed value change · includes flows</em>'}</small></div><svg class="value-chart" viewBox="0 0 820 255" role="img" aria-label="Portfolio USD snapshot history"><defs><linearGradient id="valueFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="var(--accent)" stop-opacity=".26"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{const v=lo+(hi-lo)*i/3;return `<line x1="60" x2="805" y1="${y(v)}" y2="${y(v)}" stroke="var(--line)" stroke-dasharray="3 5"/><text x="2" y="${y(v)+4}" fill="var(--muted)" font-size="10">${money(v)}</text>`;}).join('')}${shown.length>1?`<path d="${path} L ${x(maxT)} 225 L ${x(minT)} 225 Z" fill="url(#valueFill)"/><path d="${path}" fill="none" stroke="var(--accent)" stroke-width="2.8"/>`:``}${shown.map(p=>`<circle cx="${x(p.time)}" cy="${y(p.value)}" r="${shown.length===1?6:3}" fill="var(--accent)"><title>${esc(new Date(p.time).toLocaleString('en-US')+' · '+money(p.value))}</title></circle>`).join('')}<text x="60" y="250" fill="var(--muted)" font-size="10">${date(new Date(minT).toISOString())}</text><text x="800" y="250" text-anchor="end" fill="var(--muted)" font-size="10">${date(new Date(maxT).toISOString())}</text></svg>`;
}
function portfolioChart(){return panel('Portfolio value',shownData.source==='demo'?'Illustrative demo snapshots':'Observed USD snapshots · stored in this browser',lineChart(),'chart-panel',`<div class="segmented">${['7','30','all'].map(r=>`<button class="${r===chartRange?'active':''}" data-chart="${r}">${r==='all'?'All':r==='7'?'7D':'1M'}</button>`).join('')}</div>`);}
function allocationPanel(){if(privateMode)return panel('Asset allocation','Hidden in private mode',`<div class="private-chart">${icon('eye-off')}<h3>Allocation hidden</h3><p>No asset values or percentages are shown.</p></div>`,'allocation-panel');const all=holdings(),a=allocation(all),total=pricedTotal(all),unknown=all.filter(h=>!h.nft&&h.valueUsd==null).length;let start=0;const colors=['var(--accent)','var(--cyan)','var(--amber)'];return panel('Asset allocation','SOL / ETH / everything else',total?`<div class="allocation"><svg viewBox="0 0 180 180" role="img" aria-label="Allocation of priced holdings"><circle cx="90" cy="90" r="65" fill="none" stroke="var(--line)" stroke-width="18"/>${a.map((item,i)=>{const offset=start;start+=item.percent;return `<circle cx="90" cy="90" r="65" fill="none" stroke="${colors[i]}" stroke-width="18" pathLength="100" stroke-dasharray="${item.percent} ${100-item.percent}" stroke-dashoffset="${-offset}" transform="rotate(-90 90 90)"><title>${item.symbol}: ${item.percent.toFixed(1)}% (${money(item.value)})</title></circle>`;}).join('')}<text x="90" y="84" text-anchor="middle" fill="var(--muted)" font-size="10">PRICED HOLDINGS</text><text x="90" y="105" text-anchor="middle" fill="var(--ink)" font-size="17" font-weight="600">${money(total)}</text></svg><div class="allocation-list">${a.map((item,i)=>`<div><span><i style="background:${colors[i]}"></i>${item.symbol}</span><b>${item.percent.toFixed(1)}%</b></div>`).join('')}</div><p class="coverage">${unknown?unknown+' unpriced holdings excluded.':'Based on all priced holdings, including hidden dust.'}</p></div>`:empty('Allocation unavailable',shownData.balanceUsd>0?'A wallet total was returned, but item-level USD values could not be read. Export the schema to identify the response format.':'No priced holdings have been returned.',shownData.source==='live'?btn('Export response schema','portfolio-schema'):'' ),'allocation-panel');}
function cashFlow(){if(privateMode)return panel('Incoming & outgoing','Hidden in private mode','<div class="private-chart"><h3>Flow chart hidden</h3><p>Amounts and chart heights are hidden.</p></div>');const sourceRows=periodRows(),chainHashes=new Set(sourceRows.filter(r=>r.source==='On-chain'&&r.hash).map(r=>r.hash)),rows=sourceRows.filter(r=>!(r.source==='This connection'&&r.hash&&chainHashes.has(r.hash))),m=ledgerMetrics(rows);const counts=m.incoming==null||m.outgoing==null;const buckets=Array.from({length:7},()=>({in:0,out:0}));const days=$('period').value==='all'?Math.max(7,...rows.map(r=>Math.ceil((Date.now()-Date.parse(r.date))/86400000)+1)):$('period').value;for(const r of rows){if(r.status!=='success'||!['deposit','payment'].includes(r.type))continue;const i=6-Math.min(6,Math.floor((Date.now()-Date.parse(r.date))/86400000/Number(days)*7));if(i>=0)buckets[i][r.type==='deposit'?'in':'out']+=counts?1:r.amountUsd??0;}const max=Math.max(1,...buckets.flatMap(b=>[b.in,b.out]));return panel('Incoming & outgoing',counts?'Completed activity counts · historical USD values unavailable':'Recorded USD flows · selected period',`<div class="flow-summary"><div><small>Incoming ${counts?'records':'USD'}</small><b>${counts?rows.filter(r=>r.type==='deposit'&&r.status==='success').length:money(m.incoming)}</b></div><div><small>Outgoing ${counts?'records':'USD'}</small><b>${counts?rows.filter(r=>r.type==='payment'&&r.status==='success').length:money(m.outgoing)}</b></div></div><div class="bar-chart">${buckets.map(b=>`<div class="bar-group"><div class="bar in" style="height:${b.in/max*100}%" title="Incoming: ${b.in}"></div><div class="bar out" style="height:${b.out/max*100}%" title="Outgoing: ${b.out}"></div></div>`).join('')}</div><div class="legend"><span class="legend-in">Incoming</span><span class="legend-out">Outgoing</span></div>`);}
function agentPanel(){const creds=shownData.credentials??[],autonomous=creds.filter(c=>c.approvalMode==='autonomous').length,approval=creds.filter(c=>['always_approve','iframe'].includes(c.approvalMode)).length;return panel('Agent access','Your grants decide what agents can do',`<div class="agent-numbers"><div><strong>${autonomous}</strong><span>Autonomous grants</span></div><div><strong>${approval}</strong><span>Approval required</span></div></div><div class="info-row">${icon('check')}<span>Lens does not sign or execute payments.</span></div>${btn('Review security & limits','security','wide')}`);}
function overview(){const h=holdings(),change=marketMove(h.filter(v=>!v.spam&&!v.dust&&!v.nft)),x=shownData.xConnection,unpriced=h.filter(v=>!v.nft&&v.valueUsd==null).length;return `<section class="stats">${stat(privateMode?'Portfolio value':unpriced?'Priced portfolio value':'Total portfolio value',money(shownData.balanceUsd),privateMode?'Hidden in private mode':shownData.balanceUsd==null?'Valuation unavailable':unpriced?`${unpriced} unpriced holdings excluded`:'Latest wallet snapshot','wallets','hero-stat')}${stat('24h market move',privateMode?'Hidden':change?`<span class="${change.usd>=0?'positive':'negative'}">${change.usd>=0?'+':''}${money(change.usd)}</span>`:'Unknown',privateMode?'Hidden in private mode':change?(change.percent>=0?'+':'')+change.percent.toFixed(2)+'% · current visible holdings':'24h prices not fully available','transactions')}${stat('Connected wallets',String(shownData.wallets?.length??0),shownData.source==='demo'?'2 example wallets':'Wallets granted to this dashboard','deposits')}${stat('X connection',x?.connected?'Connected':x?.connected===false?'Not connected':'Unknown',privateMode?'Hidden':x?.handle?'@'+esc(x.handle.replace(/^@/,''))+(shownData.source==='demo'?' · demo':''):link(safeLink(shownData.xConnectUrl)??'https://app.paybox.sh/settings','Connect X in PayBox'),'apps')}</section><div class="dashboard-grid">${portfolioChart()}${allocationPanel()}</div>${panel('Your wallets','Balances and permission modes, at a glance',walletCards(),'wallets-panel',btn('View assets','portfolio'))}<div class="two-grid">${cashFlow()}${agentPanel()}</div>${panel('Recent activity','Latest loaded requests and on-chain records',activityTable(periodRows().slice(0,6)), 'activity-panel',btn('All activity','activity'))}`;}
function holdingsTable(rows){const total=pricedTotal(holdings());return rows.length?`<div class="table-wrap"><table><thead><tr><th>Asset</th><th>Chain / wallet</th><th>Balance</th><th>Raw balance</th><th>Value USD</th><th>Allocation</th><th>24h price</th></tr></thead><tbody>${rows.map(h=>`<tr><td><div class="asset-cell"><span class="coin ${h.symbol==='SOL'?'sol':h.symbol==='ETH'?'eth':''}">${esc(h.symbol.slice(0,1))}</span><div><b>${esc(h.symbol)}</b><small>${esc(h.name)}${h.spam?' · Suspicious name':''}</small></div></div></td><td>${esc(h.chain)}<small>${esc(h.walletName)}</small></td><td class="numeric">${esc(h.display)}</td><td><code class="raw-balance">${esc(h.raw||'Unknown')}</code></td><td class="numeric">${money(h.valueUsd)}${h.priceReason?`<small>${esc(h.priceReason)}</small>`:''}</td><td>${privateMode?'Hidden':h.valueUsd==null||!total?'Unknown':(h.valueUsd/total*100).toFixed(2)+'%'}</td><td class="${h.change24h==null?'muted':h.change24h>=0?'positive':'negative'}">${privateMode?'Hidden':h.change24h==null?'Unknown':(h.change24h>=0?'+':'')+(h.change24h*100).toFixed(2)+'%'}</td></tr>`).join('')}</tbody></table></div>`:empty('No matching holdings','Try a different filter, or refresh your wallet shownData.');}
function portfolio(){const all=holdings(),chains=[...new Set(all.map(h=>h.chain))],visible=all.filter(h=>(assetTab==='nfts'?h.nft:!h.nft)&&(!hideSpam||!h.spam)&&(!hideDust||!h.dust)&&(assetChain==='all'||h.chain===assetChain)&&(selectedWallet==='all'||h.wallet===selectedWallet)&&[h.symbol,h.name,h.tokenAddress].join(' ').toLowerCase().includes(assetsQuery.toLowerCase()));const hidden=all.filter(h=>(hideSpam&&h.spam)||(hideDust&&h.dust)).length;
 return `<div class="two-grid portfolio-top">${portfolioChart()}${allocationPanel()}</div>${panel('Portfolio & holdings','Percentages use all priced holdings. Dust and suspicious-name filters can be disabled to inspect every returned asset.',`<div class="filters asset-filters"><input id="assetSearch" type="search" value="${esc(assetsQuery)}" placeholder="Search symbol, name or token address" aria-label="Search holdings"><select id="assetChain" aria-label="Filter holdings by chain"><option value="all">All chains</option>${chains.map(c=>`<option value="${esc(c)}" ${c===assetChain?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="assetWallet" aria-label="Filter holdings by wallet"><option value="all">All wallets</option>${(shownData.wallets??[]).map(w=>`<option value="${esc(w.address)}" ${w.address===selectedWallet?'selected':''}>${esc(w.name)}</option>`).join('')}</select></div><div class="filter-options"><div class="segmented"><button data-tab="tokens" class="${assetTab==='tokens'?'active':''}">Tokens</button><button data-tab="nfts" class="${assetTab==='nfts'?'active':''}">NFTs</button></div><label><input type="checkbox" id="hideDust" ${hideDust?'checked':''}> Hide dust / under $1</label><label><input type="checkbox" id="hideSpam" ${hideSpam?'checked':''}> Hide suspected spam</label><small>${hidden} hidden · name heuristic, not verification</small></div>${selectedWallet!=='all'?`<div class="selected-wallet"><code>${esc(selectedWallet)}</code>${btn('Receive / deposit','deposit')}</div>`:''}${assetTab==='nfts'&&!all.some(h=>h.nft)?empty('No NFT data provided','NFTs appear here only when the connected provider returns them. This does not mean your wallet has no NFTs.'):holdingsTable(visible)}`,'holdings-panel')}${panel('Wallet summary','Select a wallet to inspect its assets',walletCards())}`;
}
function activityTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Activity</th><th>Wallet / source</th><th>Amount</th><th>Network fee</th><th>Status</th><th>Time</th></tr></thead><tbody>${rows.map(r=>`<tr data-record="${esc(r.uiKey)}" tabindex="0" role="button" aria-label="View ${esc(r.title??r.type)} details"><td><div class="asset-cell"><span class="tx-icon ${r.type==='deposit'?'positive':''}">${icon(r.type==='deposit'?'deposits':r.type==='swap'?'transactions':'arrow')}</span><div><b>${esc(r.title??r.kind??r.type)}</b><small class="plain-summary">${esc(explainTransaction(r,{wallets:shownData.wallets??[],privateMode}).summary)}</small><div class="label-chips">${[...(r.labels??[]),...(r.contactTags??[])].map(t=>`<span class="label-chip">${esc(t)}</span>`).join('')}</div><small>${esc(r.kind??r.type)}${r.hash?' · '+esc(short(r.hash)):''}</small></div></div></td><td>${r.contactName?esc(r.contactName):esc(r.counterparty??r.wallet?short(r.counterparty??r.wallet):'Unknown counterparty')}<small>${r.contactName?'Manual label · not verified<br>':''}${esc(r.app??r.source??'Unknown app')}${r.network?' · '+esc(chainName(r.network)):''}</small></td><td class="numeric ${r.type==='deposit'?'positive':''}">${r.amount!=null?esc((r.type==='deposit'?'+':'')+(r.amountText??number(r.amount))+' '+(r.asset??'')):money(r.amountUsd)}<small>${privateMode?'Hidden':r.amountUsd==null?'USD unknown':money(r.amountUsd)}</small></td><td>${r.feeAmount!=null?esc(number(r.feeAmount)+' '+(r.feeAsset??'')):money(r.feeUsd)}</td><td>${statusBadge(r.status)}</td><td>${date(r.date)}<small>${time(r.date)}</small></td></tr>`).join('')}</tbody></table></div>`:empty('No activity found','Change the filters or search the available wallet history.');}
function activity(){const labels=[...new Set(shownData.transactions.flatMap(r=>[...(r.labels??[]),...(r.contactTags??[])]))].sort();const rows=filteredRows(),pages=Math.max(1,Math.ceil(rows.length/50));activityPage=Math.min(activityPage,pages);const m=ledgerMetrics(rows);return `<section class="mini-stats">${stat('Swap volume',money(m.swapVolume),m.swapCount+' swaps · known valuations only','transactions')}${stat('Transfers',number(m.transferCount),'Completed transfers in loaded records','deposits')}${stat('Network fees',privateMode?'Hidden':Object.keys(m.fees).length?'<span class="small-value">'+Object.entries(m.fees).map(([k,v])=>esc(number(v)+' '+k)).join('<br>')+'</span>':'Unknown','By asset · includes reported failed-tx fees','history')}${stat('Gas used',number(m.gas),'Reported gas units · not SOL fees','history')}</section>${panel('Activity timeline','This client’s requests + independently fetched on-chain records',`<div class="filters"><input id="search" type="search" value="${esc(filters.query)}" placeholder="Search activity, hash, wallet or app" aria-label="Search activity"><select id="kind" aria-label="Activity type">${[['all','All types'],['transfer','Transfers'],['swap','Swaps'],['payment','Payments'],['x402','x402 services'],['wallet_sign','Signing'],['request','Other requests']].map(([v,n])=>`<option value="${v}" ${filters.kind===v?'selected':''}>${n}</option>`).join('')}</select><select id="status" aria-label="Activity status">${[['all','All statuses'],['success','Completed'],['pending','Pending'],['error','Failed'],['denied','Denied']].map(([v,n])=>`<option value="${v}" ${filters.status===v?'selected':''}>${n}</option>`).join('')}</select><select id="walletFilter" aria-label="Activity wallet"><option value="all">All wallets</option>${(shownData.wallets??[]).map(w=>`<option value="${esc(w.address)}" ${filters.wallet===w.address?'selected':''}>${esc(w.name)}</option>`).join('')}</select><select id="labelFilter" aria-label="Filter activity labels"><option value="all">All labels</option>${labels.map(t=>`<option value="${esc(t)}" ${filters.label===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="date-filters"><label>From (UTC)<input id="dateFrom" type="date" value="${esc(filters.from)}"></label><label>To (UTC)<input id="dateTo" type="date" value="${esc(filters.to)}"></label>${btn('Reset filters','reset-filters')}<span>${rows.length} loaded records</span>${btn('Export filtered CSV','csv')}</div>${activityTable(rows.slice((activityPage-1)*50,activityPage*50))}<div class="pagination"><button id="prevPage" ${activityPage===1?'disabled':''}>Previous</button><span>Page ${activityPage} / ${pages}</span><button id="nextPage" ${activityPage===pages?'disabled':''}>Next</button></div>`,'activity-panel')}<details class="history-details" open><summary>Automatic wallet history search <span>${historyState.rows.length} on-chain records loaded</span></summary><div id="historySection"></div></details>`;}
function insights(){if(privateMode)return '<p class="coverage">Portfolio observations are hidden in private mode.</p>';const h=holdings().filter(h=>!h.spam&&!h.nft),total=pricedTotal(h),big=h.filter(v=>v.valueUsd!=null).sort((a,b)=>b.valueUsd-a.valueUsd)[0],all=[];if(big&&total&&big.valueUsd/total>.6)all.push({title:'Asset concentration',text:`${big.symbol} represents ${(big.valueUsd/total*100).toFixed(1)}% of priced, non-spam holdings. Review your allocation and target weights before rebalancing.`,action:'portfolio'});if(h.some(v=>v.symbol==='SOL'&&v.valueUsd>0))all.push({title:'Compare SOL & USDC exposure',text:'SOL has market-price risk. Compare your short-term spending needs with your stablecoin balance; USDC also carries issuer and depeg risk. No conversion is executed by Lens.',action:'swap'});if(shownData.balanceUsd!=null&&shownData.balanceUsd<lowBalance)all.push({title:'Low wallet value',text:`The reported portfolio is below your ${money(lowBalance)} alert threshold. Check fee-token balances before making a transaction.`,action:'deposit'});const unpriced=h.filter(v=>v.valueUsd==null).length;if(unpriced)all.push({title:'Valuation gaps',text:`${unpriced} holdings have no USD price. Portfolio change and P&L cannot be calculated reliably until those values are available.`,action:'portfolio'});const pending=shownData.transactions.filter(r=>r.status==='pending_approval').length;if(pending)all.push({title:'Approvals waiting',text:`${pending} loaded requests need approval. Review the request and destination in PayBox.`,action:'security'});all.push({title:'Discover yield tools',text:'Search enabled plugins for lending or yield tools. Review their official contracts, eligibility and risks in PayBox; Lens does not invent APYs or execute deposits.',action:'yield'});return `<div class="insights-grid">${all.map(v=>`<article class="insight"><span>${icon('apps')}</span><h3>${v.title}</h3><p>${v.text}</p>${btn('Review',''+v.action)}</article>`).join('')}</div>`;}
function groupedReport(rows){const groups={};for(const r of rows){const d=new Date(r.date);if(!Number.isFinite(+d))continue;let key=d.toISOString().slice(0,10);if(reportGrouping==='monthly')key=key.slice(0,7);if(reportGrouping==='weekly'){const days=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-days);key='Week of '+d.toISOString().slice(0,10);}const g=groups[key]??[];g.push(r);groups[key]=g;}return Object.entries(groups).sort((a,b)=>b[0].localeCompare(a[0]));}
function reports(){const rows=periodRows(),m=ledgerMetrics(rows),tax=taxRows(rows),knownGains=tax.filter(r=>r.realizedGainUsd!=null);return `<section class="stats">${stat('Recorded incoming',money(m.incoming),'Completed, priced deposits','deposits')}${stat('Recorded outgoing',money(m.outgoing),'Transfers & payments · excludes swaps','transactions')}${stat('Net cash flow',money(m.netFlow),'Incoming minus outgoing · not investment P&L','history')}${stat('Agent activity',number(m.agentCount),m.failed+' failed / denied loaded records','apps')}</section>${panel('Financial reports','Grouped by UTC date · based on loaded records only',`<div class="report-toolbar"><div class="segmented">${['daily','weekly','monthly'].map(g=>`<button data-group="${g}" class="${g===reportGrouping?'active':''}">${g[0].toUpperCase()+g.slice(1)}</button>`).join('')}</div><div class="actions">${btn('PDF','pdf')}${btn('Excel (.xlsx)','xlsx')}${btn('CSV','report-csv')}</div></div><div class="table-wrap"><table><thead><tr><th>Period</th><th>Incoming USD</th><th>Outgoing USD</th><th>Net flow USD</th><th>Swaps</th><th>Agent records</th><th>Failed</th></tr></thead><tbody>${groupedReport(rows).map(([name,list])=>{const s=ledgerMetrics(list);return `<tr><td>${name}</td><td>${money(s.incoming)}</td><td>${money(s.outgoing)}</td><td>${money(s.netFlow)}</td><td>${s.swapCount}</td><td>${s.agentCount}</td><td>${s.failed}</td></tr>`;}).join('')||'<tr><td colspan="7">No loaded records in this period.</td></tr>'}</tbody></table></div><p class="coverage">Outgoing transfers are not automatically purchases. Swaps are separate from expenses. Missing historical USD values stay unknown.</p>`)}<div class="two-grid">${panel('Observed value change','Snapshot change includes deposits, withdrawals and market movement',`<div class="stat-value">${points.length>1?money(snapshotChange(points)):money(null)}</div><p>Realized and unrealized P&L are unavailable without complete prices and cost basis. The portfolio chart begins with your first saved snapshot.</p>${btn('View value history','portfolio')}`)}${panel('Tax worksheet','A starting point for classifying recorded activity',`<div class="agent-numbers"><div><strong>${tax.length}</strong><span>Recorded movements</span></div><div><strong>${knownGains.length}</strong><span>With gain / loss inputs</span></div></div><p>${tax.length-knownGains.length} rows lack cost basis or proceeds. A transfer is not automatically a taxable disposal. Jurisdiction rules and missing history require review.</p><div class="actions">${btn('Download worksheet CSV','tax')}${btn('Excel workbook','xlsx')}</div>`)}</div>${panel('Portfolio observations','Rule-based checks from your data · no automatic trading',insights())}`;}
function pluginsPanel(){const plugins=privateMode?shownData.plugins:pluginResults??shownData.plugins??[];return panel('Plugins & opportunities','Enabled tools are not proof that a plugin originated a past transaction',`<div class="filters"><input id="pluginSearch" type="search" value="${esc(pluginQuery)}" placeholder="Search enabled plugins (e.g. yield)" aria-label="Search plugins"><button id="findPlugins" ${live?'':'disabled'}>Search PayBox</button>${link('https://app.paybox.sh/plugins','Manage plugins')}</div><div class="plugin-grid">${plugins.length?plugins.map(p=>`<article class="plugin-card">${icon('apps',true)}<h3>${esc(p.name??p.title??p.plugin_id??'Plugin')}</h3>${badge(p.status??'Reported by PayBox')}<p>${esc(p.description??'No description returned.')}</p>${link('https://app.paybox.sh/plugins','Open in PayBox')}</article>`).join(''):empty('No plugins returned',live?'Search a plugin or enable one in PayBox.':'Connect PayBox to search your enabled tools.')}</div>${shownData.pluginCursor&&!pluginResults?'<p class="coverage">Showing the first enabled-plugin page. Search to locate a specific tool.</p>':''}`);}
function manage(){return `<div class="quick-grid">${[['swap','Swap tokens','Compare assets and review the trade in PayBox.','transactions'],['send','Transfer / send to X','Resolve the recipient and approve inside PayBox.','arrow'],['deposit','Receive / deposit','Copy your public wallet address.','deposits'],['buy','Buy with MoonPay','Generate an official checkout link for your wallet.','wallets']].map(([id,name,sub,ic])=>`<button class="quick-card" data-action="${id}">${icon(ic,true)}<h3>${name}</h3><p>${sub}</p><span>Open action ${icon('arrow')}</span></button>`).join('')}</div><div class="two-grid">${panel('Agent limits & approval','Changes happen in your passkey-protected PayBox session',`<p>Review credentials, spending limits and approval modes. Lens requests a management link; it does not apply a policy change on your behalf.</p>${btn('Manage this connection','access','primary')}`)}${panel('Balance alerts','A local USD-value threshold, checked while Lens is open',`<label class="field">Low-value threshold (USD)<input id="lowThreshold" type="number" min="0" step="1" value="${privateMode?'':lowBalance}" ${privateMode?'disabled placeholder="Hidden"':''}></label><button id="saveThreshold" ${privateMode?'disabled':''}>Save threshold</button><p class="coverage">A portfolio-value alert is not a fee-balance check. No background push notifications.</p>`)}</div>${pluginsPanel()}${panel('Trending token discovery','Read-only token discovery through PayBox',`<div class="actions">${btn('Load trending tokens','trending')}${link('https://app.paybox.sh/','Explore in PayBox')}</div><div id="tokenDiscovery">${tokenResults?tokenCards(tokenResults):'<p class="coverage">Connect PayBox to fetch trending tokens. Provider feature availability may vary.</p>'}</div>`)}${panel('Current observations','Based on reported balances and loaded requests',insights())}`;}
function tokenCards(result){if(privateMode)return '<p class="coverage">Token discovery details are hidden in private mode.</p>';const rows=Array.isArray(result)?result:result?.tokens??result?.results??result?.items??[];if(!Array.isArray(rows)||!rows.length)return '<p class="coverage">No token list returned. Open Explore in PayBox to use its discovery window.</p>';return `<div class="plugin-grid">${rows.slice(0,25).map(t=>`<article class="plugin-card"><h3>${esc(t.symbol??t.name??'Token')}</h3><p>${esc(t.name??'')}</p><code>${esc(short(t.address??t.token_address??t.mint))}</code><p>${t.priceUsd!=null?money(finite(t.priceUsd)):'Price unavailable'}</p></article>`).join('')}</div>`;}
function security(){const creds=shownData.credentials??[],pending=shownData.transactions.filter(r=>r.status==='pending_approval');return `<div class="two-grid">${panel('Connection & X account','Account identity stays under your control',`<dl><dt>PayBox session</dt><dd>${live?'Connected':shownData.source==='demo'?'Demo workspace':'Not connected'}</dd><dt>X connection</dt><dd>${privateMode?'Hidden':shownData.xConnection?.connected?'@'+esc(shownData.xConnection.handle.replace(/^@/,''))+(shownData.source==='demo'?' · demo':''):shownData.xConnection?.connected===false?'Not connected':'Status unavailable from the last read'}</dd><dt>Last snapshot</dt><dd>${date(shownData.date)} ${time(shownData.date)}</dd><dt>Data source</dt><dd>${esc(shownData.source)}</dd></dl><div class="actions">${link(safeLink(shownData.xConnectUrl)??'https://app.paybox.sh/settings','Connect X / account settings')}${btn('Review grants','access')}</div>`)}${panel('Data & privacy',localAvailable()?'Local database and connection':'Local snapshots, temporary authorization',`<p>${localAvailable()?'Tokens stay in your local server. Remembered access and rotating refresh tokens are encrypted in local SQLite; reconnect when PayBox expires or revokes them. Browser snapshots, public history, contacts and preferences have an encrypted local database backup. Browser localStorage itself is not encrypted. The maintainer receives none of this local data.':'Tokens stay in tab memory and expire on reload. USD snapshots and public chain history are stored in this browser. A hosting operator can access API requests passing through their server.'} Snapshots are kept for up to 90 days, separately for each connected wallet set. No wallet keys or card details are saved.</p><div class="actions">${btn('Export snapshot JSON','snapshots-export')}${btn('Clear local snapshots','snapshots-clear')}${btn('Clear saved chain history','history-clear')}${btn('Download demo schema','sample')}</div>`)}</div>${panel('Granted credentials','Reported approval modes · limits are managed in PayBox',`<div class="table-wrap"><table><thead><tr><th>Name</th><th>Kind</th><th>Public identifier</th><th>Approval mode</th><th>Manage</th></tr></thead><tbody>${creds.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.kind)}</td><td><code>${esc(c.address?short(c.address):c.last4?'•••• '+c.last4:'Not disclosed')}</code></td><td>${badge(c.approvalMode??'Unavailable',c.approvalMode==='autonomous'?'pending':'')}</td><td>${btn('Review access','access')}</td></tr>`).join('')||'<tr><td colspan="5">No credential details available. Connect PayBox to read your grants.</td></tr>'}</tbody></table></div>${shownData.ungrantedSummary?`<p class="coverage">Ungranted credential counts: ${esc(JSON.stringify(shownData.ungrantedSummary))}. No identifiers for ungranted credentials are exposed.</p>`:''}`)}${panel('Requests awaiting approval',pending.length+' loaded requests · approve in PayBox',activityTable(pending))}${panel('Access & activity log','Local dashboard reads + requests visible to this connection',`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Result</th><th>Detail</th></tr></thead><tbody>${(privateMode?clientLog.map(r=>({...r,detail:'Hidden'})):clientLog).slice(0,50).map(r=>`<tr><td>${time(r.date)}</td><td>${esc(r.action)}</td><td>${esc(r.status)}</td><td>${esc(r.detail)}</td></tr>`).join('')||'<tr><td colspan="4">No live dashboard calls recorded in this tab.</td></tr>'}</tbody></table></div><p class="coverage">This is not the account-wide agent audit log. Other clients’ requests and vault access events are not exposed by the public API.</p>`, '',btn('Export this session log','audit'))}`;}
function render(){preparePresentation();const active=document.activeElement,focusId=active?.id,start=active?.selectionStart;applyTheme();const meta={overview:['THE BIG PICTURE','Your money. In focus.','One workspace for your wallets and your agents.'],portfolio:['EVERY ASSET, ONE PLACE','Your portfolio.','Balances, allocation and the value you have observed.'],activity:['FOLLOW THE MONEY','Every move, in view.','Requests, transfers and approvals — with their evidence.'],reports:['MAKE SENSE OF THE NUMBERS','Your financial picture.','Useful reports from the data actually available.'],contacts:['YOUR PEOPLE, YOUR LABELS','Contacts & labels.','Saved names and activity notes — clearly marked as yours.'],manage:['YOUR NEXT MOVE','Manage your money.','Discover tools and complete actions in the official PayBox flow.'],security:['YOU STAY IN CONTROL','Security & account.','Credentials, approvals and the boundaries of each connection.']}[view];$('pageEyebrow').textContent=meta[0];$('title').textContent=meta[1];$('subtitle').textContent=meta[2];$('breadcrumb').textContent='Workspace / '+views.find(v=>v[0]===view)[1];$('mode').textContent=data.source==='demo'?'Demo workspace':live?'PayBox connected':data.source==='chain'?'Public chain data':'Imported workspace';$('connect').textContent=live?'Disconnect':'Connect PayBox';$('connect').disabled=loading;$('refresh').innerHTML=icon('refresh');$('refresh').disabled=loading;$('importBtn').innerHTML=icon('upload')+'Import';$('exportBtn').innerHTML=icon('download')+'Export report';$('exportBtn').disabled=privateMode;$('exportBtn').title=privateMode?'Turn off private mode to export':'';$('nav').innerHTML=views.map(([id,name,ic])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ic,true)}<span>${name}</span></button>`).join('');$('nav').querySelectorAll('button').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
 $('notice').innerHTML=data.source==='demo'?'<span class="notice-dot"></span><b>Demo workspace</b><span>All wallets, identities and amounts shown here are fictional. Connect PayBox to load your data.</span>':data.source==='import'?'<b>Imported workspace</b><span>Attribution and prices are file-supplied claims. No real account is connected.</span>':`<span class="notice-dot"></span><b>${live?'Live balances':'Public wallet scan'}</b><span>Account-wide request history and verified sender X identities are not exposed. On-chain coverage is shown in Activity.</span>`;
 if(shownData.warnings?.length)$('notice').innerHTML+=`<details><summary>${shownData.warnings.length} data-source notices</summary>${shownData.warnings.map(w=>'<p>'+esc(w)+'</p>').join('')}</details>`;
 if(shownData.hasMore)$('notice').innerHTML+='<span class="negative">Request history reached the retrieval limit.</span>';
 if(privateMode)$('notice').innerHTML='<b>Private mode</b><span>Amounts, chart shapes, wallet names, addresses, X handles and personal labels are hidden. Copy, export and wallet actions are paused.</span>'+$('notice').innerHTML;
 $('content').innerHTML=({overview,portfolio,activity,reports,manage,contacts,security})[view]();bindContent();if(view==='activity'&&privateMode)$('historySection').innerHTML='<section class="panel private-chart"><h3>Wallet history details hidden</h3><p>Turn off private mode to inspect source addresses and provider errors.</p></section>';else if(view==='activity')historyPanel($('historySection'),{language:'en',wallets:data.source==='live'||data.source==='import'?data.wallets??[]:[],onUpdate:historyUpdated,onChange:()=>{mergeHistory();render();}});
 const focused=focusId&&$(focusId);if(focused){focused.focus?.();if(start!=null&&focused.setSelectionRange)try{focused.setSelectionRange(start,start);}catch{}}
}
function bindContent(){if($('contactSearch'))$('contactSearch').oninput=e=>{contactQuery=e.target.value;render();};document.querySelectorAll('[data-contact-edit]').forEach(b=>b.onclick=()=>contactDialog(book.contacts[Number(b.dataset.contactEdit)]?.id));document.querySelectorAll('[data-contact-delete]').forEach(b=>b.onclick=()=>{if(privateMode)return;try{commitBook(removeContact(book,book.contacts[Number(b.dataset.contactDelete)]?.id));render();toast('Contact deleted. Activity notes were kept.');}catch(e){toast(e.message);}});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-wallet]').forEach(b=>b.onclick=()=>{selectedWallet=b.dataset.wallet;assetTab='tokens';navigate('portfolio');});document.querySelectorAll('[data-record]').forEach(b=>{b.onclick=()=>details(data.transactions[Number(b.dataset.record)]);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.click();}};});document.querySelectorAll('[data-chart]').forEach(b=>b.onclick=()=>{chartRange=b.dataset.chart;render();});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{assetTab=b.dataset.tab;render();});document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{reportGrouping=b.dataset.group;render();});
 for(const[id,key]of [['search','query'],['kind','kind'],['status','status'],['walletFilter','wallet'],['dateFrom','from'],['dateTo','to'],['labelFilter','label']])if($(id))$(id).addEventListener(id==='search'?'input':'change',e=>{filters[key]=e.target.value;activityPage=1;render();});
 if($('assetSearch'))$('assetSearch').oninput=e=>{assetsQuery=e.target.value;render();};if($('assetChain'))$('assetChain').onchange=e=>{assetChain=e.target.value;render();};if($('assetWallet'))$('assetWallet').onchange=e=>{selectedWallet=e.target.value;render();};if($('hideDust'))$('hideDust').onchange=e=>{hideDust=e.target.checked;render();};if($('hideSpam'))$('hideSpam').onchange=e=>{hideSpam=e.target.checked;render();};if($('prevPage'))$('prevPage').onclick=()=>{activityPage--;render();};if($('nextPage'))$('nextPage').onclick=()=>{activityPage++;render();};
 if($('saveThreshold'))$('saveThreshold').onclick=()=>{const n=finite($('lowThreshold').value);if(n==null||n<0||n>1e12)return toast('Enter a valid nonnegative threshold.');lowBalance=n;localStorage.setItem('lens-low-balance',n);toast('Balance alert threshold saved.');render();};if($('pluginSearch'))$('pluginSearch').oninput=e=>pluginQuery=e.target.value;if($('findPlugins'))$('findPlugins').onclick=()=>action('find-plugins');
}
function exportReport(kind){if(privateMode)return toast('Turn off private mode before exporting.');const decorated=data.transactions.map(r=>decorateRecord(r,book)),rows=recordFilter(decorated,{...(view==='activity'?filters:{}),days:$('period').value}).filter(r=>view!=='activity'||matchesLabel(r)),label=$('period').options?.[$('period').selectedIndex]?.textContent??'Selected period';if(kind==='pdf')download('paybox-lens-report.pdf',pdfBytes(data,rows,label),'application/pdf');if(kind==='xlsx')download('paybox-lens-report.xlsx',excelBytes(reportSheets(data,rows,label)),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');if(kind==='csv')download('paybox-lens-activity.csv',csv(rows),'text/csv;charset=utf-8');if(kind==='tax')download('paybox-lens-tax-worksheet.csv',taxCsv(rows),'text/csv;charset=utf-8');}
function exportDialog(){if(privateMode)return toast('Turn off private mode before exporting.');dialog(`<small class="eyebrow">YOUR DATA, YOUR COPY</small><h2>Export your report</h2><p>Exports use ${view==='activity'?'the current activity filters':'the selected date period'}. Missing USD values and tax basis stay blank in data files.</p><div class="export-options"><button id="downloadPDF">PDF report <small>Readable summary & activity ledger</small></button><button id="downloadXLSX">Excel workbook <small>Summary, activity, holdings & tax worksheet</small></button><button id="downloadCSV">Activity CSV <small>Current activity records</small></button><button id="downloadTax">Tax worksheet CSV <small>Cost basis & proceeds where supplied</small></button></div>`);for(const[id,k]of [['downloadPDF','pdf'],['downloadXLSX','xlsx'],['downloadCSV','csv'],['downloadTax','tax']])$(id).onclick=()=>exportReport(k);}
function depositDialog(){const wallets=data.wallets??[];dialog(`<small class="eyebrow">RECEIVE / DEPOSIT</small><h2>Your public wallet addresses</h2><p>Use the exact address and matching network shown by the sending service. Lens does not choose a deposit network for you.</p>${wallets.map(w=>`<article class="deposit-address"><b>${esc(w.name)}</b>${badge((w.chains??[]).join(' / '))}<code>${esc(w.address??'Address unavailable')}</code><button data-copy-wallet="${esc(w.address??'')}">Copy address</button></article>`).join('')||'<p>Connect PayBox to get your own public wallet address.</p>'}${link('https://app.paybox.sh/','Open PayBox wallets')}`);document.querySelectorAll('[data-copy-wallet]').forEach(b=>b.onclick=async()=>{if(data.source==='demo')return toast('Demo wallet only. Connect PayBox before using a deposit address.');if(!detectAddress(b.dataset.copyWallet))return toast('No valid public address available.');try{await navigator.clipboard.writeText(b.dataset.copyWallet);toast('Public wallet address copied.');}catch{toast('Clipboard unavailable; copy the address manually.');}});}
function officialAction(which){const swap=which==='swap';dialog(`<small class="eyebrow">COMPLETE IN PAYBOX</small><h2>${swap?'Swap tokens':'Transfer / send to an X handle'}</h2><p>${swap?'Review the token pair, exact network, quote and slippage in PayBox. Your signing window handles authorization.':'PayBox resolves the X recipient inside its own flow. Lens has no public username-to-wallet endpoint and will not guess a recipient address.'}</p><div class="action-handoff">${icon(swap?'transactions':'arrow',true)}<div><b>Open the official action screen</b><p>Choose the wallet and review the destination before approving. Opening PayBox does not execute a transaction.</p></div></div>${link('https://app.paybox.sh/','Continue in PayBox','primary external-button')}<p class="coverage">After completion, refresh Lens. Requests created by another PayBox client may appear only through on-chain history.</p>`);}
async function toolRead(name,args={}){const epoch=sessionEpoch;if(!live)throw Error('Connect PayBox to use this feature.');try{const result=await callTool(name,args);if(epoch!==sessionEpoch)throw Error('The connection changed; reconnect and retry.');uiAudit(name,'success');return result;}catch(e){if(epoch===sessionEpoch)uiAudit(name,'error',e.message);throw e;}}
async function accessDialog(){if(!live){dialog(`<h2>Manage agent access</h2><p>Connect PayBox to request a management link for this dashboard, or open account settings.</p>${link('https://app.paybox.sh/settings','PayBox settings')}`);return;}try{const r=await toolRead('request_account_change',{note:'Review PayBox Lens credential grants, spending limits and approval modes.'}),url=safeLink(r.manage_url);if(!url)throw Error('PayBox did not return a valid management link.');dialog(`<small class="eyebrow">YOUR APPROVAL, YOUR CONTROL</small><h2>Review this connection</h2><p>Update limits, credentials and approval modes in your passkey-protected PayBox session. No change has been applied by Lens.</p>${link(url,'Manage PayBox Lens access','primary external-button')}<p class="coverage">Return here and refresh after saving changes.</p>`);}catch(e){toast(e.message);}}
function buyDialog(){if(!live){toast('Connect PayBox to generate a checkout link for your own wallet.');return;}const wallets=(data.wallets??[]).filter(w=>w.id&&detectAddress(w.address));dialog(`<small class="eyebrow">OFFICIAL MOONPAY CHECKOUT</small><h2>Buy crypto into your wallet</h2><p>Generating a link moves no funds. You choose and pay on MoonPay’s page.</p><label class="field">Destination wallet<select id="buyWallet">${wallets.map(w=>`<option value="${esc(w.id)}">${esc(w.name)}</option>`).join('')}</select></label><label class="field">Asset & exact network<select id="buyAsset"></select></label><label class="field">USD amount (optional)<input id="buyAmount" type="number" min="1" step="1" placeholder="Choose at checkout"></label><button id="createBuy" class="primary" ${wallets.length?'':'disabled'}>Generate checkout link</button><div id="buyResult"></div>`);const choices=()=>{const w=wallets.find(w=>w.id===$('buyWallet').value);$('buyAsset').innerHTML=detectAddress(w?.address)?.family==='solana'?'<option value="sol">SOL · Solana</option><option value="usdc_sol">USDC · Solana</option>':'<option value="usdc_base">USDC · Base</option><option value="eth">ETH · Ethereum</option>';};choices();$('buyWallet').onchange=choices;$('createBuy').onclick=async()=>{const b=$('createBuy'),wallet=$('buyWallet').value,asset=$('buyAsset').value,amount=$('buyAmount').value,network=asset==='eth'?'eip155:1':asset==='usdc_base'?'eip155:8453':'solana:mainnet';const n=amount===''?null:finite(amount);if(amount!==''&&(n==null||n<=0))return toast('Enter a positive USD amount or leave it blank.');b.disabled=true;const target=$('buyResult');target.innerHTML='<p class="coverage">Generating the official checkout link…</p>';try{const r=await toolRead('get_buy_link',{credential_id:wallet,destination_chain:network,currency_code:asset,...(n!=null?{amount_usd:n}:{})}),url=safeLink(r.url,'buy');if(!url)throw Error('An official MoonPay checkout URL was not returned.');const expected=wallets.find(w=>w.id===wallet)?.address;const matches=(a,b)=>a?.startsWith('0x')?a.toLowerCase()===b?.toLowerCase():a===b;if(!expected||!matches(r.wallet_address,expected))throw Error('Checkout destination does not match the selected wallet.');const linkAddress=new URL(url).searchParams.get('walletAddress');if(linkAddress&&!matches(linkAddress,expected))throw Error('Checkout link contains a different wallet address.');if(r.network&&r.network!==network)throw Error('Checkout network does not match your selection.');if(target.isConnected)target.innerHTML=`<div class="notice"><b>Checkout link ready</b><p>${esc(r.wallet_address??'')} · ${esc(r.network??network)}</p>${link(url,'Continue to MoonPay','primary external-button')}</div>`;}catch(e){if(target.isConnected)target.textContent=e.message;toast(e.message);}finally{b.disabled=false;}};}
function explanationBlock(r){const e=explainTransaction(r,{wallets:data.wallets??[],privateMode});return `<section class="transaction-explanation"><small class="eyebrow">IN PLAIN ENGLISH</small><p>${esc(e.summary)}</p><ul>${e.details.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></section>`;}
function details(record){if(!record)return;const enriched=decorateRecord(record,book),r=privateMode?redactRecord(enriched,Math.max(0,data.transactions.findIndex(v=>v.id===record.id))):enriched;
 const pairs=[['Request / record ID',r.id],['Kind',r.kind??r.type],['Status',statusName(r.status)],['Amount',r.amount==null?money(null):(r.amountText??number(r.amount))+' '+(r.asset??'')],['Historical value USD',money(r.amountUsd)],['Network fee',r.feeAmount==null?money(r.feeUsd):number(r.feeAmount)+' '+(r.feeAsset??'')],['Gas units',number(r.gasUsed)],['Wallet',r.wallet??'Not reported'],['Network',r.network?chainName(r.network):'Not reported'],['Counterparty',r.counterparty??(privateMode?'Hidden':'Not reported')],['Saved contact',r.contactName?`${r.contactName}${r.contactHandle?' (@'+r.contactHandle+')':''} · manual label; not verified`:privateMode?'Hidden':'Not saved'],['Your labels',(r.labels??[]).join(', ')||(privateMode?'Hidden':'None')],['Your note',r.note||(privateMode?'Hidden':'None')],['App / source',r.app??r.source??'Not reported'],['Identity evidence',privateMode?'Hidden':r.identityEvidence?data.source==='demo'?'Fictional demo identity':'File-supplied claim; not verified':'No verified X sender identity'],['Timestamp',r.date],['Error / denial reason',privateMode?'Hidden':r.errorReason??'No reason reported'],['Hash',r.hash??(privateMode?'Hidden':'Not reported')]];
 const explorer=privateMode?null:explorerUrl(r.hash,r.network);
 dialog(`<small class="eyebrow">ACTIVITY DETAILS</small><h2>${esc(r.title??r.type)}</h2>${explanationBlock(r)}<dl>${pairs.map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl><div class="actions"><button id="copyId" ${privateMode?'disabled':''}>Copy ID</button>${explorer?link(explorer,'View on explorer'):''}${!privateMode?'<button id="editLabels">Edit labels & note</button><button id="saveCounterparty">Save / edit contact</button>':''}${!privateMode&&live&&record.requestId?'<button id="loadRequest" class="primary">Refresh request details</button>':''}</div>${!privateMode&&safeLink(r.approvalUrl)?link(safeLink(r.approvalUrl),'Review approval in PayBox'):''}`);
 $('copyId').onclick=async()=>{if(privateMode)return;try{await navigator.clipboard.writeText(record.id);toast('Record ID copied.');}catch{toast('Clipboard unavailable.');}};
 if($('editLabels'))$('editLabels').onclick=()=>labelsDialog(record);
 if($('saveCounterparty'))$('saveCounterparty').onclick=()=>{const c=contactFor(record.counterparty,book);contactDialog(c?.id,detectAddress(record.counterparty)?.address??'');};
 if($('loadRequest'))$('loadRequest').onclick=async()=>{const b=$('loadRequest');b.disabled=true;const epoch=sessionEpoch;try{const latest=await requestDetails(record);if(epoch!==sessionEpoch)return;uiAudit('get_request','success');data.transactions=data.transactions.map(item=>item.id===record.id?{...record,...latest}:item);render();details({...record,...latest});}catch(e){if(epoch===sessionEpoch)toast(e.message);}finally{b.disabled=false;}};
}
function contacts(){if(privateMode)return panel('Contacts & labels','Hidden in private mode','<div class="private-chart">'+icon('eye-off')+'<h3>Your contacts are hidden</h3><p>Turn off private mode to manage names, addresses, X handles and notes.</p></div>');
 const matches=book.contacts.map((c,i)=>({c,i})).filter(({c})=>[c.name,c.address,c.xHandle,...c.tags,c.notes].join(' ').toLowerCase().includes(contactQuery.toLowerCase()));
 return panel('Your contact book','Stored in this browser for this workspace · names and handles are manual labels',`<div class="filters"><input id="contactSearch" type="search" value="${esc(contactQuery)}" placeholder="Search name, address, handle or tag" aria-label="Search contacts">${btn('Export contacts & labels','contacts-export')}</div><div class="contact-grid">${matches.map(({c,i})=>`<article class="contact-card"><div class="contact-card-head"><span class="avatar">${esc(c.name.slice(0,1).toUpperCase())}</span><div><h3>${esc(c.name)}</h3>${badge('Manual label · not verified')}</div></div><code>${esc(c.address)}</code>${c.xHandle?`<p>@${esc(c.xHandle)} <small>Saved by you</small></p>`:''}<div class="label-chips">${c.tags.map(t=>`<span class="label-chip">${esc(t)}</span>`).join('')}</div>${c.notes?`<p class="contact-note">${esc(c.notes)}</p>`:''}<div class="actions"><button data-contact-edit="${i}">Edit</button><button data-contact-delete="${i}">Delete</button></div></article>`).join('')||empty('No matching contacts','Save a full public wallet address and give it a name.',btn('Add a contact','contact-new','primary'))}</div><p class="coverage">${book.contacts.length} saved contacts · ${Object.keys(book.labels).length} annotated activity records. Your labels do not verify identity or change the original transaction data.</p>`,'contacts-panel',btn('Add contact','contact-new','primary'));
}
function commitBook(next){saveBook(localStorage,bookScope,next);book=next;}
function contactDialog(id=null,address=''){if(privateMode)return toast('Turn off private mode to edit contacts.');const scope=bookScope,c=id?book.contacts.find(c=>c.id===id):null;
 dialog(`<small class="eyebrow">YOUR CONTACT BOOK</small><h2>${c?'Edit':'Add'} contact</h2><p>This name and X handle are your own labels. Lens does not verify identity or use this address to send funds.</p><label class="field">Name<input id="contactName" maxlength="80" value="${esc(c?.name??'')}" placeholder="e.g. MoonPay / my other wallet"></label><label class="field">Full public wallet address<input id="contactAddress" maxlength="100" value="${esc(c?.address??address)}" autocomplete="off" placeholder="0x… or Solana address"></label><label class="field">X handle (optional, unverified)<input id="contactHandle" maxlength="16" value="${esc(c?.xHandle??'')}" placeholder="@handle"></label><label class="field">Tags (comma-separated, up to 8)<input id="contactTags" value="${esc(c?.tags.join(', ')??'')}" maxlength="250" placeholder="Work, Income, Personal"></label><label class="field">Private note<textarea id="contactNotes" maxlength="500" rows="3">${esc(c?.notes??'')}</textarea></label><p id="contactError" role="alert" class="negative"></p><button id="saveContact" class="primary">Save contact</button>`);
 const save=()=>{try{if(scope!==bookScope)throw Error('Workspace changed. Open the contact again.');commitBook(upsertContact(book,{name:$('contactName').value,address:$('contactAddress').value,xHandle:$('contactHandle').value,tags:$('contactTags').value,notes:$('contactNotes').value},c?.id??null));$('dialog').close();$('dialogContent').innerHTML='';render();toast('Contact saved in this browser.');}catch(e){$('contactError').textContent=e.message;}};
 $('saveContact').onclick=save;for(const id of ['contactName','contactAddress','contactHandle','contactTags'])$(id).onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();save();}};
}
function labelsDialog(record){if(privateMode)return toast('Turn off private mode to edit labels.');const scope=bookScope,current=Object.hasOwn(book.labels,record.id)?book.labels[record.id]:{tags:[],note:''};
 dialog(`<small class="eyebrow">YOUR ACTIVITY LABELS</small><h2>Labels & note</h2><p>These annotations stay on this record after refresh. They are your notes, not proof of sender or plugin identity.</p><label class="field">Tags (comma-separated, up to 8)<input id="activityTags" maxlength="250" value="${esc(current.tags.join(', '))}" placeholder="Sponsored, Invoice, Personal"></label><label class="field">Private note<textarea id="activityNote" maxlength="500" rows="4">${esc(current.note)}</textarea></label><p id="labelsError" role="alert" class="negative"></p><button id="saveLabels" class="primary">Save labels</button>`);
 $('saveLabels').onclick=()=>{try{if(scope!==bookScope)throw Error('Workspace changed. Open this record again.');commitBook(setRecordLabels(book,record.id,{tags:$('activityTags').value,note:$('activityNote').value}));render();details(data.transactions.find(r=>r.id===record.id)??record);}catch(e){$('labelsError').textContent=e.message;}};
}
async function action(name){if(privateMode&&['swap','send','buy','deposit','access','contact-new','contacts-export'].includes(name))return toast('Turn off private mode to use this action.');if(name==='contact-new')return contactDialog();if(name==='contacts-export')return download('paybox-lens-contacts-and-labels.json',JSON.stringify(book,null,2),'application/json');if(['overview','portfolio','activity','reports','manage','contacts','security'].includes(name))return navigate(name);if(name==='connect')return $('connect').click();if(name==='swap'||name==='send')return officialAction(name);if(name==='deposit')return depositDialog();if(name==='buy')return buyDialog();if(name==='access')return accessDialog();if(name==='csv'||name==='report-csv')return exportReport('csv');if(['pdf','xlsx','tax'].includes(name))return exportReport(name);if(name==='reset-filters'){filters={query:'',kind:'all',status:'all',wallet:'all',from:'',to:''};activityPage=1;return render();}if(name==='snapshot'){captureSnapshot();render();return toast('Current available USD snapshot saved.');}if(name==='history-clear'){clearHistoryCache(localStorage,data.wallets??[]);resetHistory(true);data.transactions=data.transactions.filter(r=>r.source!=='On-chain');render();return toast('Saved chain history for these wallets cleared.');}if(name==='snapshots-export')return download('paybox-lens-snapshots.json',JSON.stringify({version:1,source:data.source,wallets:(data.wallets??[]).map(w=>w.address),snapshots:points},null,2),'application/json');if(name==='snapshots-clear'){localStorage.removeItem(snapshotKey(data.wallets??[]));points=[];render();return toast('Snapshots for this wallet set cleared.');}if(name==='portfolio-schema')return download('paybox-lens-portfolio-schema.json',JSON.stringify(portfolioSchema(data.portfolio??[]),null,2),'application/json');if(name==='sample')return download('paybox-lens-sample.json',JSON.stringify(demoData(),null,2),'application/json');if(name==='audit')return download('paybox-lens-session-log.json',JSON.stringify({scope:'This browser tab only',events:clientLog},null,2),'application/json');if(name==='yield'){pluginQuery='yield';navigate('manage');if(!live)return toast('Connect PayBox to search enabled yield plugins.');return action('find-plugins');}if(name==='find-plugins'){try{const r=await toolRead('discover_plugins',{status:'enabled',...(pluginQuery?{query:pluginQuery}:{})});pluginResults=Array.isArray(r)?r:r.plugins??r.results??[];render();}catch(e){toast(e.message);}return;}if(name==='trending'){try{tokenResults=await toolRead('discover_tokens',{mode:'trending'});render();}catch(e){toast(e.message);}return;}}
function mergeHistory(){const chain=historyRows();data.transactions=[...data.transactions.filter(r=>r.source!=='On-chain'),...chain];}
function historyUpdated(s){if(data.source==='demo'){data={version:1,source:'chain',balanceUsd:null,transactions:[],portfolio:[],plugins:[],wallets:s.wallets,credentials:[],date:new Date().toISOString()};points=[];}mergeHistory();render();}
async function loadLive(){if(pendingLive)return pendingLive;const epoch=sessionEpoch;pendingLive=(async()=>{loading=true;render();try{const next=await snapshot();if(epoch!==sessionEpoch)return;data=next;live=true;pluginResults=null;tokenResults=null;uiAudit('Wallets, portfolio, requests, plugins','success');configureHistory(next.wallets??[]);mergeHistory();setPoints();captureSnapshot();render();if(next.wallets?.length&&!historyState.busy)syncHistory({all:true,refresh:historyState.complete,onUpdate:historyUpdated});}catch(e){if(epoch===sessionEpoch){uiAudit('Refresh','error',e.message);throw e;}}finally{if(epoch===sessionEpoch){loading=false;pendingLive=null;render();}}})();return pendingLive;}
$('connect').onclick=()=>{if(live){$('dialog').close();$('dialogContent').innerHTML='';sessionEpoch++;pendingLive=null;loading=false;disconnect();resetHistory(true);live=false;clientLog=[];data=demoData();filters={query:'',kind:'all',status:'all',wallet:'all',from:'',to:''};selectedWallet='all';pluginResults=null;tokenResults=null;setPoints();render();return;}dialog(`<small class="eyebrow">CONNECT YOUR WORKSPACE</small><h2>Connect PayBox</h2><p>Read your granted wallets, balances, this client’s requests and enabled plugins. History scanning uses public chain providers.</p><p>${localAvailable()?'Local mode: tokens stay in the local server, never in browser JavaScript. If you choose remembered sign-in, rotating PayBox tokens are encrypted in your local SQLite database. Snapshots, contacts and history also have a local database backup. The maintainer does not receive this data.':'Hosted mode: tokens stay in tab memory. A hosting operator can access requests passing through their server. Access tokens are not saved by Lens. Browser snapshots and contacts remain local.'} Your linked X account is read from PayBox. Sender identities and other clients’ audit logs may be unavailable.</p><p>Swaps, transfers and permission changes are completed in the official PayBox flow.</p>${localAvailable()?'<label class="field"><span><input id="rememberConnection" type="checkbox"> Keep me signed in on this device</span><small>Requests offline_access in PayBox. Uncheck on a shared device. Expiry or revocation still requires reconnecting.</small></label>':''}<button id="startConnect" class="primary">Continue to PayBox</button>`);$('startConnect').onclick=async()=>{const b=$('startConnect');b.disabled=true;try{await connect({remember:Boolean($('rememberConnection')?.checked)});}catch(e){b.disabled=false;toast(e.message);}};};
$('refresh').onclick=async()=>{if(!live){render();return toast('Local workspace refreshed. Connect PayBox for live data.');}try{await loadLive();toast('Wallet snapshot refreshed.');}catch(e){toast(e.message);}};
$('importBtn').onclick=()=>{if(live)return toast('Disconnect before importing a separate dataset.');$('file').click();};
$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5*1024*1024)throw Error('Import must be smaller than 5 MB.');const next=validateData(JSON.parse(await f.text()));sessionEpoch++;resetHistory(true);data=next;points=[];filters={query:'',kind:'all',status:'all',wallet:'all',from:'',to:''};selectedWallet='all';navigate('overview');toast('Workspace imported. File-supplied identities are not verified.');}catch(err){toast(err.message);}finally{e.target.value='';}};
$('exportBtn').onclick=exportDialog;
setPoints();render();document.addEventListener('lens-local-error',()=>toast('Local database backup failed. Browser data is retained; retry or export a backup.'));try{const restored=await initializeLocal();if(localAvailable()){theme=localStorage.getItem('lens-theme')??'dark';palette=localStorage.getItem('lens-palette')??'purple';privateMode=localStorage.getItem('lens-private-mode')==='1';setPoints();render();}if(await callback()||restored.connected){await loadLive();toast(restored.connected?'Saved local PayBox connection restored.':'PayBox connected. History search runs automatically.');}}catch(e){toast(e.message);}
setInterval(async()=>{if(!live||loading||document.hidden)return;try{await loadLive();}catch(e){toast('Scheduled refresh: '+e.message);}},900000);
